define("theme_learnlingo/footer_settings",[],function(){"use strict";const init=()=>{const select=document.getElementById("id_s_theme_learnlingo_footermode");if(!select){return}const getSettingRow=name=>{const input=document.getElementById("id_s_theme_learnlingo_"+name);return document.getElementById("admin-"+name)||document.getElementById("admin-theme_learnlingo_"+name)||input?.closest(".form-item, .fitem, .form-group")};const setVisible=(element,visible)=>{if(!element){return}element.classList.toggle("d-none",!visible);element.setAttribute("aria-hidden",visible?"false":"true")};const setColumnHeadingVisible=(index,visible)=>{const row=getSettingRow("footer_title_"+index);const previous=row?.previousElementSibling;if(previous?.matches("h3.main")){setVisible(previous,visible)}};const refresh=()=>{const isHtml=select.value==="html";setVisible(getSettingRow("footerhtml"),isHtml);setVisible(getSettingRow("footerscss"),isHtml);setVisible(getSettingRow("footer_background_color"),!isHtml);for(let index=1;index<=4;index++){setColumnHeadingVisible(index,!isHtml);setVisible(getSettingRow("footer_title_"+index),!isHtml);setVisible(getSettingRow("footer_html_"+index),!isHtml)}setVisible(getSettingRow("footer_show_copywriter"),!isHtml)};select.addEventListener("change",refresh);refresh()};return{init:init}});